# From the native value of a OrderStatus.
def fromnative_order_status(n):
    kind = type(n)
    if kind is data.OrderStatusPlaced:
        return 2
    if kind is data.OrderStatusApproved:
        return 0
    if kind is data.OrderStatusDelivered:
        return 1
    raise TypeError("expected OrderStatus")


